  function commandUrl(){var s=String(state.station.sessionId||""),p=s.indexOf("@");return p>0?"https://iot.ioeasy.com/cmd/"+encodeURIComponent(s.slice(0,p))+"?apiKey="+encodeURIComponent(s.slice(p+1)):""}
  function version(){var d=new Date(),pad=function(v){return String(v).padStart(2,"0")};return[d.getFullYear(),pad(d.getMonth()+1),pad(d.getDate()),pad(d.getHours()),pad(d.getMinutes()),pad(d.getSeconds())].join("")}
