  function resolveTemplate(template,values){var result=String(template||"");Object.keys(values).forEach(function(k){result=result.split("{"+k+"}").join(String(values[k]))});var resolver=window.AIBridgeCommandTemplate;return resolver&&resolver.resolveCommandTemplate?resolver.resolveCommandTemplate(result):Promise.resolve(result)}
