  function postMacro(payload){return fetch(macroUrl(),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload||{})}).then(function(r){return r.json().catch(function(){return null}).then(function(data){if(!r.ok)throw new Error(data&&data.error||"Không thể truy cập cơ sở dữ liệu.");state.dbAvailable=true;return Array.isArray(data)?data:data&&Array.isArray(data.rows)?data.rows:[]})})}
  function requestId(prefix){return(prefix||"FP")+"-"+Date.now().toString(36).toUpperCase()+"-"+Math.random().toString(36).slice(2,7).toUpperCase()}
  function dbAudit(category,action,status,detail,payload,req){var a=state.config.audit||{},macro=a.writeMacro||"fuel-audit-write";return postMacro({macro:macro,category:category,action:action,status:status,request_id:req||requestId("AUD"),actor:"<<username>>",station_id:(state.config.ledSettings||{}).stationId||"default",detail:detail||"",payload_json:JSON.stringify(payload||{})}).then(function(){return loadDbLogs()}).catch(function(){return null})}
  function auditActionLabel(action){var labels={send_prices:"Gửi bảng giá",set_brightness:"Đặt độ sáng tức thời",set_brightness_schedule:"Cập nhật lịch độ sáng",send_led_settings:"Gửi cấu hình bảng LED",save_led_settings:"Lưu cài đặt bảng LED",board_led_on:"Bật toàn bảng LED",board_led_off:"Tắt toàn bảng LED",price_mode_manual:"Chọn nguồn nhập tay",price_mode_online:"Chọn nguồn Petrolimex",price_region:"Chọn vùng giá",fetch_online_prices:"Lấy giá Petrolimex",test:"Kiểm tra hệ thống"};return labels[action]||String(action||"Sự kiện hệ thống").replace(/_/g," ")}
  function commandSubject(action,values){values=values||{};if(action==="send_prices")return"bảng giá phiên bản "+text(values.version,"không rõ")+", nguồn "+(values.source==="online"?"Petrolimex":"nhập tay")+", Vùng "+text(values.region,"1")+" ["+String(values.payload||"").replace(/\|/g,"; ")+"]";if(action==="set_brightness")return"độ sáng tức thời "+text(values.value,"?")+"/10";if(action==="set_brightness_schedule")return"lịch độ sáng ["+String(values.payload||"").replace(/\|/g,"; ")+"]";if(action==="board_led_on")return"lệnh bật hiển thị toàn bảng LED";if(action==="board_led_off")return"lệnh tắt hiển thị toàn bảng LED";if(action==="send_led_settings"){var cfg={};String(values.payload||"").split("|").forEach(function(x){var i=x.indexOf("=");if(i>0)cfg[x.slice(0,i)]=x.slice(i+1)});return"cấu hình bảng LED: địa chỉ "+text(cfg.ADDR,"?")+", kênh "+text(cfg.CH,"?")+", "+(cfg.FACE==="one"?"1 mặt":"2 mặt cùng nội dung")+", quạt "+(cfg.FAN==="auto"?"tự động":"liên tục")+", kết nối "+text(cfg.LINK,"không rõ")+", các hàng ["+text(cfg.ROWS,"chưa có")+"]"}return auditActionLabel(action)}
  function commandAuditDetail(action,values,status,error){var subject=commandSubject(action,values);if(status==="pending")return"Đang gửi "+subject+" xuống thiết bị.";if(status==="success")return"Gateway đã nhận "+subject+".";return"Gửi "+subject+" thất bại: "+text(error,"Lỗi không xác định")}
  function toast(message,type){var n=document.createElement("div");n.className="fp-toast "+(type||"");n.textContent=message;id("fp-toasts").appendChild(n);setTimeout(function(){n.remove()},4200)}
  function logKey(){return"rosa-fuel-log-"+String(state.station&&state.station.sessionId||"station").replace(/[^a-z0-9_-]/gi,"_")}
